Problem Description:
The following adder-subtractor with zero flag doesn't work. Fix the bug(s).

// synthesis verilog_input_version verilog_2001
// module top_module ( 
//     input do_sub,
//     input [7:0] a,
//     input [7:0] b,
//     output reg [7:0] out,
//     output reg result_is_zero
// );//

//     always @(*) begin
//         case (do_sub)
//           0: out = a+b;
//           1: out = a-b;
//         endcase

//         if (~out)
//             result_is_zero = 1;
//     end

// endmodule

module top_module (
	input do_sub,
	input [7:0] a,
	input [7:0] b,
	output reg [7:0] out,
	output reg result_is_zero
);

Erroneous Implementation:

always @(posedge clk) begin
    case (do_sub)
        0: out <= a + b;
        1: out <= a - b;
    endcase

    if (out == 0)
        result_is_zero <= 1;
    else
        result_is_zero <= 0;
end


endmodule

Feedback:
bugs_addsubz.sv:190: error: Unable to bind wire/reg/memory `clk' in `tb.top_module1'
bugs_addsubz.sv:190: error: Failed to evaluate event expression 'posedge clk'.
2 error(s) during elaboration.

```verilog
module top_module (
    input do_sub,
    input [7:0] a,
    input [7:0] b,
    output reg [7:0] out,
    output reg result_is_zero
);

    always @(*) begin
        // Determine whether to add or subtract
        case (do_sub)
            1'b0: out = a + b;
            1'b1: out = a - b;
            default: out = 8'b0;
        endcase

        // Determine if the result is zero
        if (out == 8'b0)
            result_is_zero = 1'b1;
        else
            result_is_zero = 1'b0;
    end

endmodule
```
